import {FEATURE_NAMES,validateRecords,logisticContributions} from './inference.mjs';
import {parseCSV,rankScores,labelledMetrics,MAX_BYTES} from './lab-core.mjs';
const $=id=>document.getElementById(id), money=n=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD',maximumFractionDigits:0}).format(n),pct=n=>n===null||n===undefined?'N/A':(n*100).toFixed(1)+'%';
const state={models:null,metrics:null,demo:null,records:[],scores:[],features:[],ranked:[],alerts:new Set(),selected:0,labelsUsable:true,edited:new Set(),worker:null,loaded:false};
function node(tag,text,cls){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el;}
function showError(message){$('load-error').textContent=message;$('load-error').classList.remove('hidden');$('run-status').textContent=message;}
function clearError(){$('load-error').classList.add('hidden');}
function busy(value){['run','scenario','model','budget','csv-file'].forEach(id=>$(id).disabled=value||!state.loaded);document.querySelectorAll('#detail button,#detail input').forEach(el=>el.disabled=value);}
function setTab(name){if(!['lab','method','results','about'].includes(name))name='lab';document.querySelectorAll('.view').forEach(el=>el.classList.toggle('hidden',el.id!=='view-'+name));document.querySelectorAll('[data-tab]').forEach(el=>{el.classList.toggle('active',el.dataset.tab===name);if(el.dataset.tab===name)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});history.replaceState(null,'','#'+name);}
document.querySelectorAll('[data-tab]').forEach(el=>el.addEventListener('click',()=>setTab(el.dataset.tab)));window.addEventListener('hashchange',()=>setTab(location.hash.slice(1)));setTab(location.hash.slice(1));
async function loadJSON(path){const r=await fetch(path);if(!r.ok)throw Error('Could not load '+path);return r.json();}
function updateBudget(){const b=Number($('budget').value);$('budget-value').textContent=b+'%';$('budget-copy').textContent=b+'%';if(state.scores.length){rerank();renderResults();}}
$('budget').addEventListener('input',updateBudget);
function rerank(){const ranked=rankScores(state.records,state.scores,Number($('budget').value));Object.assign(state,ranked);}
async function analyze(preferredId){
  clearError();busy(true);$('run-status').textContent='Computing historical features and running the trained model…';
  try{
    validateRecords(state.records);if(state.records.length>5000)throw Error('Limit is 5,000 records.');
    if(state.worker)state.worker.terminate();
    const worker=new Worker('./inference-worker.mjs',{type:'module'});state.worker=worker;
    const result=await new Promise((resolve,reject)=>{worker.onmessage=e=>e.data.error?reject(Error(e.data.error)):resolve(e.data);worker.onerror=()=>reject(Error('The inference worker could not run. Try a current browser.'));worker.postMessage({records:state.records,models:state.models,model:$('model').value});});
    worker.terminate();state.worker=null;state.scores=result.scores;state.features=result.features;rerank();
    state.selected=preferredId?Math.max(0,state.records.findIndex(r=>r.id===preferredId)):state.ranked[0].index;
    renderResults();$('run-status').textContent=`Analyzed ${state.records.length.toLocaleString()} transfers locally. ${state.k} selected for review.`;
    return {rows:state.records.length,alerts:state.k,model:$('model').value};
  }catch(e){if(state.worker){state.worker.terminate();state.worker=null;}state.scores=[];state.features=[];state.ranked=[];state.alerts=new Set();state.k=0;$('queue-count').textContent='No results';$('graph-context').textContent='No results';$('queue').replaceChildren();$('graph').replaceChildren();$('detail').classList.add('hidden');$('detail-empty').classList.remove('hidden');['stat-total','stat-alerts','stat-precision','stat-recall'].forEach(id=>$(id).textContent='—');showError(e.message);return null;}finally{busy(false);}
}
function selectScenario(){const selected=$('scenario').value;const all=selected==='uploaded'?state.uploaded:state.demo.records;
  state.records=all.map(r=>({...r}));state.labelsUsable=true;state.edited.clear();
  if(selected==='benign'){state.records=state.records.filter(r=>r.label===0);$('scenario-description').textContent='Benign-only subset. History is recomputed; this is a new self-contained scene, not a benchmark partition.';}
  else if(selected==='uploaded'){state.labelsUsable=state.records.every(r=>r.label===0||r.label===1);$('scenario-description').textContent='Uploaded local stream. Unknown/partial labels produce N/A metrics.';}
  else $('scenario-description').textContent='A self-contained two-day scene, generated with a separate seed from the benchmark. Includes benign payments and planted patterns.';
  analyze();
}
$('scenario').addEventListener('change',selectScenario);$('model').addEventListener('change',()=>analyze(state.records[state.selected]?.id));$('run').addEventListener('click',()=>analyze(state.records[state.selected]?.id));
function renderResults(){
  const m=labelledMetrics(state.records,state.alerts,state.labelsUsable);$('stat-total').textContent=state.records.length.toLocaleString();$('stat-alerts').textContent=state.k.toLocaleString();$('stat-precision').textContent=pct(m.precision);$('stat-recall').textContent=pct(m.recall);$('queue-count').textContent=state.k+' review alerts';
  $('queue').replaceChildren();
  state.ranked.slice(0,15).forEach(({record:r,index,score})=>{
    const tr=node('tr',undefined,index===state.selected?'selected-row':'');const first=node('td');const b=node('button',r.id,'row-select');b.addEventListener('click',()=>{state.selected=index;renderResults();});first.append(b);tr.append(first,node('td',r.sender+' → '+r.receiver));tr.append(node('td',money(r.amount),'numeric'));
    const s=node('td',undefined,'numeric'),wrap=node('div',undefined,'score'),track=node('span',undefined,'score-line'),fill=node('i');fill.style.width=(score*100)+'%';track.append(fill);wrap.append(track,node('span',score.toFixed(3)));s.append(wrap);tr.append(s);const q=node('td');q.append(node('span',state.alerts.has(index)?'Review':'Below budget',state.alerts.has(index)?'queue-tag':'queue-tag quiet'));tr.append(q);$('queue').append(tr);
  });renderDetail();renderGraph();
}
function renderDetail(){
  const r=state.records[state.selected],f=state.features[state.selected];if(!r||!f)return;$('detail-empty').classList.add('hidden');$('detail').classList.remove('hidden');const d=$('detail');d.replaceChildren();
  const top=node('div',undefined,'detail-header');top.append(node('h3',r.id),node('div',state.scores[state.selected].toFixed(3),'detail-score'),node('span','Synthetic-label model score','detail-label'));d.append(top);
  const fields=node('dl',undefined,'detail-fields');for(const [k,v] of [['Sender',r.sender],['Receiver',r.receiver],['Time (UTC)',r.timestamp.replace('T',' ').replace('Z','')],['Amount',money(r.amount)],['Planted label',state.labelsUsable&&r.label!==undefined?(r.label?'Suspicious pattern':'Benign'):'Unknown / edited']]){const x=node('div');x.append(node('dt',k),node('dd',v));fields.append(x);}d.append(fields);
  d.append(node('h3','Strictly prior context'));
  const facts=[['Sender outgoing transfers',Math.round(Math.expm1(f[1]))+' in prior 24h'],['Sender incoming volume',money(Math.expm1(f[6]))+' in prior 24h'],['Unique sender recipients',Math.round(Math.expm1(f[7]))+' in prior 24h'],['Amount / prior average',f[8].toFixed(2)+'× (capped at 20)']];
  facts.forEach(([a,b])=>{const x=node('div',undefined,'feature-item');x.append(node('strong',a),node('span',b));d.append(x);});
  if($('model').value==='logistic'){d.append(node('h3','Additive model contributions'));const contributions=logisticContributions(f,state.models.models.logistic).sort((a,b)=>Math.abs(b.contribution)-Math.abs(a.contribution)).slice(0,3);for(const c of contributions){const x=node('div',undefined,'feature-item');x.append(node('strong',c.feature.replaceAll('_',' ')),node('span',(c.contribution>=0?'+':'')+c.contribution.toFixed(2)+' to model log-odds'));d.append(x);}d.append(node('p','Conditional model contributions; not causal explanations.','detail-note'));}
  else d.append(node('p','These are observed input features, not attributions of the forest prediction. Select Logistic Regression to inspect additive model contributions.','detail-note'));
  const edit=node('form',undefined,'amount-edit'),label=node('label','Change the amount');label.htmlFor='edit-amount';const input=node('input');input.id='edit-amount';input.type='number';input.min='.01';input.max='1000000000';input.step='.01';input.value=r.amount;input.required=true;const button=node('button','Apply & recompute','primary');button.type='submit';edit.append(label,input,button);edit.addEventListener('submit',e=>{e.preventDefault();const amount=Number(input.value);if(!Number.isFinite(amount)||amount<=0||amount>1e9){showError('Amount must be positive and at most CAD 1 billion.');return;}r.amount=amount;delete r.label;state.edited.add(r.id);state.labelsUsable=false;analyze(r.id);});d.append(edit);
  if(state.edited.size)d.append(node('p','Edited scene: precision/recall are hidden because the original labels no longer describe the modified experiment. Reload a preset to reset.','edited'));
}
function svg(tag,attrs={}){const e=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v] of Object.entries(attrs))e.setAttribute(k,String(v));return e;}
function renderGraph(){
  const r=state.records[state.selected],container=$('graph');container.replaceChildren();if(!r)return;
  const t=Date.parse(r.timestamp),past=state.records.filter(x=>Date.parse(x.timestamp)<t&&Date.parse(x.timestamp)>=t-86400000&&(x.sender===r.sender||x.receiver===r.sender||x.sender===r.receiver||x.receiver===r.receiver)).slice(-18);
  const names=[r.sender,r.receiver];for(const x of past){for(const a of [x.sender,x.receiver])if(!names.includes(a)&&names.length<10)names.push(a);}
  const edges=past.filter(x=>names.includes(x.sender)&&names.includes(x.receiver));$('graph-context').textContent=edges.length+' prior transfers shown';
  const root=svg('svg',{viewBox:'0 0 620 280',role:'group','aria-label':`Historical account network around ${r.id}. ${edges.length} prior transfers shown.`});const title=svg('title');title.textContent='Prior 24-hour account neighborhood';root.append(title);
  const defs=svg('defs'),marker=svg('marker',{id:'edge-arrow',markerWidth:6,markerHeight:6,refX:5,refY:3,orient:'auto'});marker.append(svg('path',{d:'M0 0L6 3L0 6',fill:'#879ab3'}));defs.append(marker);root.append(defs);
  const pos=new Map();names.forEach((a,i)=>{const angle=2*Math.PI*i/names.length-Math.PI/2;pos.set(a,{x:310+Math.cos(angle)*225,y:140+Math.sin(angle)*100});});
  edges.forEach(x=>{const a=pos.get(x.sender),b=pos.get(x.receiver),dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy)||1;const edge=svg('line',{x1:a.x+dx/len*22,y1:a.y+dy/len*22,x2:b.x-dx/len*25,y2:b.y-dy/len*25,stroke:'#a1b3ca','stroke-width':1.7,'marker-end':'url(#edge-arrow)'});const tip=svg('title');tip.textContent=x.sender+' to '+x.receiver+': '+money(x.amount);edge.append(tip);root.append(edge);});
  names.forEach(a=>{const p=pos.get(a),primary=a===r.sender||a===r.receiver;const group=svg('g',{tabindex:0,role:'button','aria-label':'Inspect transactions involving '+a});group.append(svg('circle',{cx:p.x,cy:p.y,r:primary?20:15,fill:primary?'#007f80':'#6b7d96',stroke:'#fff','stroke-width':3}));const txt=svg('text',{x:p.x,y:p.y+35,'text-anchor':'middle',fill:'#344861','font-size':12,'font-weight':primary?700:500});txt.textContent=a.length>13?a.slice(0,11)+'…':a;group.append(txt);const full=svg('title');full.textContent=a;group.append(full);const choose=()=>{const match=state.ranked.find(x=>x.record.sender===a||x.record.receiver===a);if(match){state.selected=match.index;renderResults();}};group.addEventListener('click',choose);group.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose();}});root.append(group);});
  container.append(root);
}
function renderMethod(){const m=state.metrics.metadata;const list=$('feature-list');list.replaceChildren();FEATURE_NAMES.forEach(f=>list.append(node('li',f.replaceAll('_',' '))));const split=$('split-detail');split.replaceChildren();for(const [name,d] of Object.entries(m.splits)){split.append(node('h3',name[0].toUpperCase()+name.slice(1)),node('p',`${d.rows.toLocaleString()} rows · ${d.positives.toLocaleString()} planted positives · ${d.start.slice(0,10)} to ${d.end.slice(0,10)}`));}}
function renderEvaluation(){const names={tabular_logistic:'Logistic · amount only',tabular_forest:'Forest · amount only',tabular_isolation:'Isolation · amount only',historical_logistic:'Logistic · history',historical_forest:'Forest · history',historical_isolation:'Isolation · history',amount_rule:'High-amount rule'};const body=$('metrics-table');body.replaceChildren();const chart=$('ap-chart');chart.replaceChildren();for(const [key,report] of Object.entries(state.metrics.results)){const r=report.test,b=r.budgets.find(x=>x.fraction===.05),tr=node('tr');tr.append(node('td',names[key]||key));[r.averagePrecision,r.rocAuc,b?.precision,b?.recall].forEach(x=>tr.append(node('td',x===null||x===undefined?'N/A':x.toFixed(3),'numeric')));body.append(tr);const bar=node('div',undefined,'bar-row');const desc=node('div');desc.append(node('span',names[key]||key),node('strong',r.averagePrecision===null?'N/A':r.averagePrecision.toFixed(3)));const track=node('div',undefined,'bar-track'),fill=node('i');fill.style.width=(Math.max(0,r.averagePrecision??0)*100)+'%';track.append(fill);bar.append(desc,track);chart.append(bar);}
  const m=state.metrics.metadata,baseline=node('div',undefined,'bar-row baseline'),desc=node('div');desc.append(node('span','Positive prevalence'),node('strong',(m.splits.test.positives/m.splits.test.rows).toFixed(3)));const track=node('div',undefined,'bar-track'),fill=node('i');fill.style.width=(m.splits.test.positives/m.splits.test.rows*100)+'%';track.append(fill);baseline.append(desc,track);chart.append(baseline);
  const manifest=$('experiment-manifest');manifest.replaceChildren();const grid=node('div',undefined,'manifest-grid');for(const [a,b] of [['Total rows',m.rows.toLocaleString()],['Generator seed',m.seed],['Planted positives',m.positives.toLocaleString()],['Test window',m.splits.test.rows.toLocaleString()+' rows']]){const x=node('div');x.append(node('span',a),node('strong',String(b)));grid.append(x);}manifest.append(grid,node('p','Data SHA-256: '+m.sha256,'help code'),node('p','Versions: '+Object.entries(m.versions).map(([a,b])=>a+' '+b).join(' · '),'help'),node('p',m.trainingPolicy));
}
$('csv-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;clearError();try{if(file.size>MAX_BYTES)throw Error('CSV must be at most 5 MB.');const records=parseCSV(await file.text());validateRecords(records);state.uploaded=records.map(r=>({...r}));state.records=records;state.labelsUsable=records.every(r=>r.label===0||r.label===1);state.edited.clear();$('scenario').querySelector('option[value="uploaded"]')?.remove();$('scenario').append(new Option('Uploaded: '+file.name,'uploaded'));$('scenario').value='uploaded';$('scenario-description').textContent='Uploaded local stream: '+file.name+'. Unknown/partial labels produce N/A evaluation metrics.';await analyze();}catch(error){showError(error.message);}finally{e.target.value='';}});
$('csv-example').addEventListener('click',()=>{if(!state.demo){showError('Wait for the example data to load.');return;}const headers=['id','timestamp','sender','receiver','amount','currency'];const text=[headers.join(','),...state.demo.records.map(r=>headers.map(h=>String(r[h])).join(','))].join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv'}));const a=node('a');a.href=url;a.download='aml-radar-example.csv';a.click();URL.revokeObjectURL(url);});
async function init(){try{[state.models,state.metrics,state.demo]=await Promise.all(['./artifacts/models.json','./artifacts/metrics.json','./artifacts/demo.json'].map(loadJSON));if(JSON.stringify(state.models.features)!==JSON.stringify(FEATURE_NAMES))throw Error('Model and feature contract do not match.');state.loaded=true;$('model-version').textContent='v0.1 · Model schema '+state.models.schemaVersion;
  $('model').replaceChildren(new Option('Random Forest · history','forest'),new Option('Logistic Regression · history','logistic'));$('scenario').replaceChildren(new Option('Mixed transactions · planted patterns','mixed'),new Option('Benign-only stream','benign'));busy(false);renderMethod();renderEvaluation();selectScenario();registerTools();
}catch(e){showError(e.message);}}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});try{Promise.resolve(context.registerTool({name:'configure_and_run_transaction_lab',title:'Configure and run AML Radar',description:'Choose a synthetic preset, trained model and review budget, then run local inference and update the visible lab.',inputSchema:{type:'object',properties:{scenario:{type:'string',enum:['mixed','benign']},model:{type:'string',enum:['forest','logistic']},budget:{type:'integer',minimum:1,maximum:10}},required:['scenario','model','budget'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},async execute(input){if(!input||Object.keys(input).some(k=>!['scenario','model','budget'].includes(k))||!['mixed','benign'].includes(input.scenario)||!['forest','logistic'].includes(input.model)||!Number.isInteger(input.budget)||input.budget<1||input.budget>10)throw Error('Invalid lab configuration.');if(state.worker)throw Error('An analysis is already running.');$('scenario').value=input.scenario;$('model').value=input.model;$('budget').value=input.budget;setTab('lab');state.records=state.demo.records.filter(r=>input.scenario!=='benign'||r.label===0).map(r=>({...r}));state.labelsUsable=true;state.edited.clear();$('scenario-description').textContent=input.scenario==='benign'?'Benign-only subset; historical context is recomputed.':'Self-contained synthetic mixed stream; separate from benchmark.';const result=await analyze();if(!result)throw Error('Analysis failed; inspect the visible error.');updateBudget();return result;}},{signal:life.signal})).catch(()=>{});}catch{}}
init();
